class Solution {
    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
        return join(word1).equals(join(word2));
    }

    private String join(String[] words) {
        StringBuilder builder = new StringBuilder();
        for (String word : words) {
            builder.append(word);
        }
        return builder.toString();
    }
}

class Solution {
    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
        int i = 0, j = 0;
        int a = 0, b = 0;

        while (i < word1.length && j < word2.length) {
            if (word1[i].charAt(a) != word2[j].charAt(b)) {
                return false;
            }

            a++;
            b++;
            if (a == word1[i].length()) {
                i++;
                a = 0;
            }
            if (b == word2[j].length()) {
                j++;
                b = 0;
            }
        }

        return i == word1.length && j == word2.length;
    }
}

class Solution {
    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
        CharStream left = new CharStream(word1);
        CharStream right = new CharStream(word2);

        while (left.hasNext() && right.hasNext()) {
            if (left.next() != right.next()) {
                return false;
            }
        }
        return !left.hasNext() && !right.hasNext();
    }

    private static class CharStream {
        private final String[] words;
        private int wordIndex;
        private int charIndex;

        CharStream(String[] words) {
            this.words = words;
        }

        boolean hasNext() {
            return wordIndex < words.length;
        }

        char next() {
            char current = words[wordIndex].charAt(charIndex);
            charIndex++;
            if (charIndex == words[wordIndex].length()) {
                wordIndex++;
                charIndex = 0;
            }
            return current;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public boolean arrayStringsAreEqual(String[] word1, String[] word2) {
        Deque<Character> left = toQueue(word1);
        Deque<Character> right = toQueue(word2);

        while (!left.isEmpty() && !right.isEmpty()) {
            if (left.removeFirst() != right.removeFirst()) {
                return false;
            }
        }
        return left.isEmpty() && right.isEmpty();
    }

    private Deque<Character> toQueue(String[] words) {
        Deque<Character> queue = new ArrayDeque<>();
        for (String word : words) {
            for (int i = 0; i < word.length(); i++) {
                queue.addLast(word.charAt(i));
            }
        }
        return queue;
    }
}
